import { Controller } from "@hotwired/stimulus"
import { formatLocalTime } from "helpers/date_helpers"

export default class extends Controller {
  static targets = [ "time" ]

  #timer

  connect() {
    this.#renderAll()
    this.#timer = setInterval(this.#renderAll, 60_000)
    document.addEventListener("turbo:render", this.#renderAll)
    document.addEventListener("turbo:frame-render", this.#renderAll)
  }

  disconnect() {
    clearInterval(this.#timer)
    document.removeEventListener("turbo:render", this.#renderAll)
    document.removeEventListener("turbo:frame-render", this.#renderAll)
  }

  timeTargetConnected(element) {
    this.#render(element)
  }

  #renderAll = () => this.timeTargets.forEach(this.#render)

  #render = element => {
    const timestamp = element.dateTime
    const format = element.dataset.localTimeFormat
    const text = formatLocalTime(timestamp, format)

    if (text) {
      element.textContent = text
      if (!element.hasAttribute("title")) {
        element.title = formatLocalTime(timestamp, "full")
      }
    }
  }
}
EOF
