  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(value, format = "relative", now = new Date()) {
  if (value == null || value === "") return ""

  const date = parseDate(value)

  if (Number.isNaN(date.getTime())) return ""

  switch (format) {
    case "time":
      return dateFormatter({ hour: "numeric", minute: "2-digit" }).format(date)
    case "date":
      return shortDate(date, now)
    case "date-long":
      return dateFormatter({ month: "short", day: "numeric", year: "numeric" }).format(date)
    case "date-time":
      return dateFormatter({ month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" }).format(date)
    case "weekday":
      return dateFormatter({ weekday: "long", month: "long", day: "numeric" }).format(date)
    case "full":
      return dateFormatter({ weekday: "long", year: "numeric", month: "long", day: "numeric", hour: "numeric", minute: "2-digit" }).format(date)
    case "until":
      return relativeDateFormatter().format(signedDifferenceInDays(now, date), "day")
    case "relative":
    default:
      return relativeOrDate(date, now)
  }
}

function relativeOrDate(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatLocalTime(date, "time")
  } else if (Math.abs(days) < 7) {
    return relativeDateFormatter().format(days, "day")
  } else {
    return shortDate(date, now)
  }
}

function shortDate(date, now) {
  const options = { month: "short", day: "numeric" }
  if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"
  return dateFormatter(options).format(date)
}

function parseDate(value) {
  if (value instanceof Date) return value

  const dateParts = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value))
  if (dateParts) {
    return new Date(Number(dateParts[1]), Number(dateParts[2]) - 1, Number(dateParts[3]))
  }

  return new Date(value)
}

const formatterCache = new Map()

function dateFormatter(options) {
  return formatter("date", options)
}

function relativeDateFormatter() {
  return formatter("relative", { numeric: "auto" })
}

function formatter(type, options) {
  const locale = document.documentElement.lang || "en"
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone
  const key = `${type}:${locale}:${timezone}:${JSON.stringify(options)}`

  if (!formatterCache.has(key)) {
    formatterCache.set(key, type === "relative"
      ? new Intl.RelativeTimeFormat(locale, options)
      : new Intl.DateTimeFormat(locale, { ...options, timeZone: timezone }))
  }

  return formatterCache.get(key)
}

