require "application_system_test_case"

class LocalTimeTest < ApplicationSystemTestCase
  test "formats timestamps in the browser timezone" do
    page.driver.browser.execute_cdp("Emulation.setTimezoneOverride", timezoneId: "America/Los_Angeles")
    sign_in_as(users(:kevin))

    browser_timezone = page.driver.browser.execute_script("return Intl.DateTimeFormat().resolvedOptions().timeZone")
    assert_equal "America/Los_Angeles", browser_timezone

    formatted = page.driver.browser.execute_async_script(<<~JS)
      const done = arguments[arguments.length - 1]
      import("helpers/date_helpers").then(({ formatLocalTime }) => {
        const now = new Date("2025-09-13T02:00:00.000Z")
        done([
          formatLocalTime("2025-09-13T00:42:00.000Z", "relative", now),
          formatLocalTime("2025-09-12T06:00:00.000Z", "relative", now),
          formatLocalTime("2025-09-07T19:00:00.000Z", "relative", now),
          formatLocalTime("2025-09-05T19:00:00.000Z", "relative", now),
          formatLocalTime("2025-09-13T08:00:00.000Z", "until", now),
          formatLocalTime("2025-09-16T02:00:00.000Z", "until", now),
          formatLocalTime("2025-03-09T08:30:00.000Z", "relative", new Date("2025-03-10T07:30:00.000Z"))
        ])
      }).catch(error => done({ error: error.message }))
    JS

    assert_equal [ "5:42 PM", "yesterday", "5 days ago", "Sep 5", "tomorrow", "in 3 days", "yesterday" ], formatted

    comment = comments(:logo_agreement_kevin)
    zone = ActiveSupport::TimeZone["America/Los_Angeles"]
    local_now = Time.current.in_time_zone(zone)
    comment.update!(created_at: zone.local(local_now.year, local_now.month, local_now.day, 9, 42))

    visit card_url(comment.card)

    assert_selector "a.comment__permalink-title time[datetime='#{comment.created_at.utc.iso8601(3)}']", text: "9:42 AM"
  end
end

class LocalTimeAutoCloseTest < ApplicationSystemTestCase
  test "auto-close dates use relative days in the browser timezone" do
    page.driver.browser.execute_cdp("Emulation.setTimezoneOverride", timezoneId: "America/Los_Angeles")
    sign_in_as(users(:kevin))

    card = cards(:logo)
    zone = ActiveSupport::TimeZone["America/Los_Angeles"]
    card.board.entropy.update!(auto_postpone_period: 3.days)
    card.update!(last_active_at: zone.now - 2.days)

    visit card_url(card)
    assert_text /Moves to “Not Now” tomorrow if there’s no activity/

    card.update!(last_active_at: zone.now)
    visit card_url(card)
    assert_text /Moves to “Not Now” in 3 days if there’s no activity/
  end
end
"
}

